/**
 * Batch processing state management for calendar page.
 *
 * Two-phase start: `requestStart` stages `pending` (provider +
 * workouts) so a confirmation dialog can render estimated tokens/cost
 * before the user commits; `confirmStart` dispatches the actual run
 * (delegated to `useBatchRunner`).
 */

import { useLiveQuery } from "dexie-react-hooks";
import { useCallback, useState } from "react";

import { db } from "../../adapters/dexie/dexie-database";
import type { BatchResult } from "../../application/batch-processor";
import { useToastContext } from "../../contexts/ToastContext";
import { useTranslate } from "../../i18n/use-translate";
import type { LlmProviderConfig } from "../../store/ai-store-types";
import type { WorkoutRecord } from "../../types/calendar-record";
import { prepareBatch } from "./batch-prepare";
import { useBatchRunner } from "./use-batch-runner";

export type BatchPending = {
  provider: LlmProviderConfig;
  modelId: string;
  workouts: WorkoutRecord[];
  /** The sport the run was staged for; absent means every sport. */
  sport?: string;
};

/** Fired once a run resolves cleanly, before the send chain (if any). */
export type BatchDone = (result: BatchResult, batch: BatchPending) => void;

export function useBatchState(
  weekStart: string,
  weekEnd: string,
  onDone?: BatchDone
) {
  const t = useTranslate("calendar");
  const [message, setMessage] = useState<string | null>(null);
  const [pending, setPending] = useState<BatchPending | null>(null);
  const { success: showSuccess } = useToastContext();
  // The static translation-key title satisfies the R-PIIInterpolation
  // guard; the dynamic counts flow through the description field. A row
  // skipped because it changed meanwhile is not counted as processed.
  const runner = useBatchRunner(setMessage, (result, batch) => {
    const count = result.succeeded.length + result.failed.length;
    const skipped = result.skipped.length;
    const description = skipped
      ? t("batch.workoutsProcessedSkipped", { count, skipped })
      : t("batch.workoutsProcessed", { count });
    showSuccess(t("batch.processed"), description, { duration: 3000 });
    onDone?.(result, batch);
  });

  const providerCount = useLiveQuery(() => db.table("aiProviders").count(), []);

  const requestStart = useCallback(
    async (options?: { sport?: string }) => {
      if (!providerCount || providerCount === 0) {
        setMessage(t("batch.noProvider"));
        return;
      }
      const prep = await prepareBatch(weekStart, weekEnd, options?.sport);
      if (!prep.ok) {
        setMessage(prep.message);
        return;
      }
      setMessage(null);
      setPending({
        provider: prep.provider,
        modelId: prep.modelId,
        workouts: prep.workouts,
        ...(options?.sport ? { sport: options.sport } : {}),
      });
    },
    [weekStart, weekEnd, providerCount, t]
  );

  const confirmStart = useCallback(async () => {
    const staged = pending;
    if (!staged) return;
    setPending(null);
    await runner.run(staged);
  }, [pending, runner]);

  const cancelRequest = useCallback(() => setPending(null), []);
  const dismissMessage = useCallback(() => setMessage(null), []);

  return {
    isProcessing: runner.isProcessing,
    progress: runner.progress,
    message,
    pending,
    requestStart,
    confirmStart,
    cancelRequest,
    cancel: runner.cancel,
    dismissMessage,
  };
}
