/**
 * The calendar's send workflow: the "Send week" state plus the "Running: AI
 * then Garmin" action that stages the week's RAW running workouts for the AI
 * batch and, once that run resolves, sends every running workout of the week
 * to the Garmin calendar. The send candidates are built from the batch
 * result, not from the live query, so a row the AI just structured is not
 * skipped as still `raw`.
 */
import { useCallback, useMemo } from "react";

import { isProjectedWorkoutRecord } from "../../application/coaching/activity-to-workout-record";
import {
  RUNNING_SPORT,
  selectRunAndSendCandidates,
} from "../../application/garmin-bulk/run-and-send-candidates";
import type { useCalendarData } from "./calendar-hooks";
import { useBatchState } from "./use-batch-state";
import { useCalendarSendWeek } from "./use-calendar-send-week";

type CalendarData = ReturnType<typeof useCalendarData>;

export type CalendarRunAndSend = {
  batch: ReturnType<typeof useBatchState>;
  offered: boolean;
  start: () => void;
};

export function useCalendarWorkflow(
  profileId: string | null,
  data: CalendarData
) {
  const send = useCalendarSendWeek(profileId, data.weekId, data.workoutsByDay);
  const running = useMemo(
    () =>
      Object.values(data.workoutsByDay)
        .flat()
        .filter(
          (workout) =>
            !isProjectedWorkoutRecord(workout) &&
            workout.sport === RUNNING_SPORT
        ),
    [data.workoutsByDay]
  );
  const batch = useBatchState(
    data.weekStart,
    data.weekEnd,
    (result, staged) => {
      if (staged.sport !== RUNNING_SPORT) return;
      send.start(selectRunAndSendCandidates(running, result));
    }
  );
  const start = useCallback(() => {
    void batch.requestStart({ sport: RUNNING_SPORT });
  }, [batch]);
  const runAndSend: CalendarRunAndSend = {
    batch,
    offered: send.offered && send.state.phase === "idle" && running.length > 0,
    start,
  };
  return { batch, send, runAndSend };
}
