/**
 * Candidates for "Running: AI then Garmin": the week's running workouts,
 * with eligibility resolved against the batch that just ran. A row the AI
 * structured is eligible even though the live query may still show it `raw`
 * (the batch write and the query are not ordered), and a row the batch
 * failed or skipped is reported `not-eligible` instead of being sent with
 * the stale content it had before.
 */
import type { WorkoutRecord } from "../../types/calendar-record";
import type { BatchResult } from "../batch-processor";
import type { WeekPushCandidate } from "./select-week-push-candidates";
import { selectWeekPushCandidates } from "./select-week-push-candidates";

/** KRD `metadata.sport` of a running session. */
export const RUNNING_SPORT = "running";

export const selectRunAndSendCandidates = (
  workouts: readonly WorkoutRecord[],
  result: BatchResult,
  sport: string = RUNNING_SPORT
): WeekPushCandidate[] => {
  const structured = new Set(result.succeeded);
  const leftRaw = new Set([
    ...result.failed.map((failure) => failure.id),
    ...result.skipped,
  ]);
  const inSport = workouts.filter((workout) => workout.sport === sport);
  return selectWeekPushCandidates(inSport).map((candidate) => {
    const { workoutId, date } = candidate;
    if (leftRaw.has(workoutId)) return { workoutId, date, notEligible: "raw" };
    if (!structured.has(workoutId)) return candidate;
    return { workoutId, date };
  });
};
