/**
 * The "Running: AI then Garmin" action for the nav row. It hides while its
 * own batch runs (the progress banner and the send panel take over) and
 * whenever the week has no running workout or no active Garmin route.
 */
import { useTranslate } from "../../i18n/use-translate";
import { Button } from "../atoms/Button";
import type { CalendarRunAndSend } from "./use-calendar-workflow";

export function RunAndSendButton({
  runAndSend,
}: {
  runAndSend: CalendarRunAndSend;
}) {
  const t = useTranslate("calendar");
  if (!runAndSend.offered || runAndSend.batch.isProcessing) return null;
  return (
    <Button
      size="sm"
      variant="secondary"
      onClick={runAndSend.start}
      data-testid="calendar-run-and-send"
    >
      {t("runAndSend.action")}
    </Button>
  );
}
